SELECT id, project_id, deliverable_code, name, stage_code, task_code, required,
       source_definition_id, status, current_source_version_id, archive_status, version,
       creator, create_time, updater, update_time, deleted, tenant_id
FROM acc_project_deliverable
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND deliverable_code = #{query.deliverableCode}
  AND deleted = 0
FOR UPDATE

SELECT *
FROM acc_project_deliverable
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.deliverableId}
  AND deleted = b'0'
FOR UPDATE

mapper.update:
UPDATE acc_project_deliverable
SET current_source_version_id = NULL,
    archive_status = 'INVALID',
    version = version + 1,
    updater = #{query.updater},
    update_time = NOW()
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.deliverableId}
  AND current_source_version_id = #{query.expectedCurrentSourceVersionId}
  AND version = #{query.expectedRootVersion}
  AND deleted = b'0'
